build.py.source:
import hashlib,json,os,pathlib,shutil,subprocess,sys,time
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-fields-path').read_text().strip()); s=r/(sys.argv[2] if len(sys.argv)>2 else 'source'); label=sys.argv[1]
def hashes():
 result={}
 for directory,dirs,files in os.walk(s):
  dirs[:]=[d for d in dirs if d not in ['target','.git']]
  for name in files:
   if name.endswith('.rs'):
    p=pathlib.Path(directory)/name; result[str(p.relative_to(s))]=hashlib.sha256(p.read_bytes()).hexdigest()
 return result
before=hashes(); cmd=['rtk','proxy','cargo','build','--offline','--release','-p','tsr','--bin','tsr']; env=os.environ.copy(); env['CARGO_BUILD_JOBS']='2'; env['CARGO_TARGET_DIR']=str(s/'target'); started=time.monotonic()
with (r/(label+'.stdout')).open('w') as out,(r/(label+'.stderr')).open('w') as err:
 p=subprocess.Popen(cmd,cwd=s,env=env,stdout=out,stderr=err); print(json.dumps({'label':label,'pid':p.pid,'command':cmd}),flush=True); rc=p.wait()
after=hashes(); assert before==after
record={'command':cmd,'pid':p.pid,'returncode':rc,'seconds':time.monotonic()-started,'source_unchanged_during_build':True,'source_hashes_before':before,'source_hashes_after':after,'stdout':(r/(label+'.stdout')).read_text(),'stderr':(r/(label+'.stderr')).read_text()}
if rc==0:
 exe=r/(label+'-tsr'); shutil.copy2(s/'target/release/tsr',exe); record['binary']={'path':str(exe),'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()}
(r/(label+'.json')).write_text(json.dumps(record,indent=2)+'\n'); assert json.loads((r/(label+'.json')).read_text())==record; print(json.dumps({'label':label,'returncode':rc,'seconds':record['seconds']})); print(record['stderr'][-1500:]); sys.exit(rc)

control-measure.py.source:
import hashlib,importlib.util,json,os,pathlib,sys
sys.dont_write_bytecode=True
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-fields-path').read_text().strip()); setup=json.loads((r/'setup.json').read_text()); prior=pathlib.Path(setup['prior_archive'])
spec=importlib.util.spec_from_file_location('perf','<repo>/scripts/whole_project_perf.py'); perf=importlib.util.module_from_spec(spec); spec.loader.exec_module(perf)
fixtures={
 'fields':"interface Base<T> {base:T;(v:T):T;new(v:T):{v:T};[key:string]:T} interface Mid<U> extends Base<U> {mid:U;[key:string]:U} interface Leaf extends Mid<number> {leaf:number} declare const leaf:Leaf; const ok:number=leaf.base; const bad:string=leaf.mid;",
 'identities':"namespace Left { export interface Box<T,U> {left:T;right:U} } namespace Right { export interface Box<T,U> {left:U;right:T} } interface Empty {} declare const a:Left.Box<number,string>; declare const b:Left.Box<string,number>; declare const c:Right.Box<number,string>; const first:number=a.left; const second:number=b.right; const other:number=c.right; const bad:string=a.left;",
 'reset':"class BaseType<T> {bar:T} class NextType<C extends {someProp:any},T=C['someProp']> extends BaseType<T> {baz:string} class Foo extends NextType<Foo> {someProp:{test:true}} const foo=new Foo(); const probe=foo.bar.test;",
}
folder=r/'controls';folder.mkdir(exist_ok=False)
for name,source in fixtures.items():(folder/(name+'.ts')).write_text(source+'\n')
ordinary={'main':setup['baseline_reuse']['binary'],'publication':json.loads((prior/'member-alias-build.json').read_text())['binary']}; observer={'main':json.loads((r/'legacy-storage.json').read_text())['binary'],'publication':json.loads((r/'publication-storage.json').read_text())['binary']}
for key in list(os.environ):
 if key.startswith(('TSR_','TSGO_','RAYON_')):os.environ.pop(key)
paths=[str(p) for p in folder.glob('*')]+[b['path'] for b in list(ordinary.values())+list(observer.values())]+[setup['native_binary']['path']]+[str(p) for p in (r/'source/vendor/typescript-go/internal/bundled/libs').glob('*')]
reference=perf.inputs.snapshot(paths);rows=[]
for name in fixtures:
 for mode in ['single','default']:
  for role in ['native','main','publication']:
   for phase in (['ordinary'] if role=='native' else ['ordinary','off','count','time','count-repeat']):
    binary=setup['native_binary'] if role=='native' else ordinary[role] if phase=='ordinary' else observer[role]
    assert hashlib.sha256(pathlib.Path(binary['path']).read_bytes()).hexdigest()==binary['sha256']
    if phase in ['count','count-repeat']:os.environ['TSR_MEMBER_FIELD_COST']='count'
    elif phase=='time':os.environ['TSR_MEMBER_FIELD_COST']='time'
    else:os.environ.pop('TSR_MEMBER_FIELD_COST',None)
    before=perf.inputs.snapshot(paths); command=[binary['path'],'--ignoreConfig','--pretty','false','--noEmit','--target','es2020','--strict','false','--skipLibCheck','true',str(folder/(name+'.ts'))]
    if mode=='single':command+=['--singleThreaded','true']
    row=perf.process(command,folder,120);events=[]
    for line in row['stderr'].splitlines():
     prefix,payload=line.split(' ',1);assert prefix in ['MEMBER_LEGACY','MEMBER_PUBLICATION','MEMBER_SYMBOL_STORAGE'];events.append({'kind':prefix,'counts':json.loads(payload)})
    row.update(fixture=name,role=role,mode=mode,phase=phase,events=events,observed_inputs_stable=before==perf.inputs.snapshot(paths)==reference,binary_sha256=binary['sha256']);rows.append(row)
    (r/'controls-progress.json').write_text(json.dumps({'rows':rows,'complete':False},indent=2)+'\n')
    assert row['observed_inputs_stable'] and not row['timed_out']
    original=next(v for v in rows if v['fixture']==name and v['role']==role and v['mode']==mode and v['phase']=='ordinary')
    assert row['stdout']==original['stdout'] and row['exit_code']==original['exit_code']
    if phase in ['ordinary','off']:assert events==[]
    else:assert events
    print(json.dumps({'fixture':name,'mode':mode,'role':role,'phase':phase,'exit_code':row['exit_code']}),flush=True)
record={'rows':rows,'complete':True,'fixtures':fixtures,'input_fingerprint':perf.fingerprint(reference),'driver_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()};(r/'controls.json').write_text(json.dumps(record,indent=2)+'\n');assert json.loads((r/'controls.json').read_text())==record

