        let start = self.member_publication.cost.legacy.enter(0);
        let result = self.publication_image_work(key);
        self.member_publication.cost.legacy.exit(0,start,result);
        result
    }

    fn publication_image_work(&mut self, key:ImageKey) -> bool {''')
replace('            && image.published { return true; }','''            && image.published {
            if self.member_publication.cost.legacy.enabled {
                if image.done { self.member_publication.cost.completed_hits += 1; }
                else { self.member_publication.cost.active_hits += 1; }
            }
            return true;
        }''')
replace('        }) else { return false; };','''        }) else {
            if self.member_publication.cost.legacy.enabled { self.member_publication.cost.unsupported += 1; }
            return false;
        };''')
replace('        if !self.binder.symbols().get(owner).flags.intersects(SymbolFlags::CLASS | SymbolFlags::INTERFACE) { return false; }','''        if !self.binder.symbols().get(owner).flags.intersects(SymbolFlags::CLASS | SymbolFlags::INTERFACE) {
            if self.member_publication.cost.legacy.enabled { self.member_publication.cost.unsupported += 1; }
            return false;
        }
        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.image_workers += 1; }''')
replace('        if let Some(fields)=self.member_publication.declared.get(&owner) {return fields.clone();}','''        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.declared_calls += 1; }
        if let Some(fields)=self.member_publication.declared.get(&owner) {
            if self.member_publication.cost.legacy.enabled {
                if let Some(fields)=fields {
                    self.member_publication.cost.declared_hits += 1;
                    self.member_publication.cost.copy(0, Self::publication_copy_counts(fields));
                } else { self.member_publication.cost.declared_none_hits += 1; }
            }
            return fields.clone();
        }
        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.declared_workers += 1; }''')
replace('        self.member_publication.declared.insert(owner,Some(fields.clone()));','''        if self.member_publication.cost.legacy.enabled {
            self.member_publication.cost.copy(1, Self::publication_copy_counts(&fields));
        }
        self.member_publication.declared.insert(owner,Some(fields.clone()));''')
replace('        self.member_publication.declared.insert(owner,finished.clone());','''        if self.member_publication.cost.legacy.enabled && let Some(fields)=&finished {
            self.member_publication.cost.copy(2, Self::publication_copy_counts(fields));
        }
        self.member_publication.declared.insert(owner,finished.clone());''')
replace('        self.publication_set_fields(key,fields.clone());','''        if self.member_publication.cost.legacy.enabled {
            self.member_publication.cost.copy(3, Self::publication_copy_counts(&fields));
        }
        self.publication_set_fields(key,fields.clone());''')
replace('            let inherited=StructuredFields {members:base_image.members.clone(),calls:base_image.calls.clone(),constructs:base_image.constructs.clone(),indexes:base_image.indexes.clone()};','''            if self.member_publication.cost.legacy.enabled {
                let counts=[base_image.members.len() as u64,base_image.members.keys().map(|name|name.len() as u64).sum(),base_image.calls.len() as u64,base_image.constructs.len() as u64,base_image.indexes.len() as u64];
                self.member_publication.cost.copy(4, counts);
            }
            let inherited=StructuredFields {members:base_image.members.clone(),calls:base_image.calls.clone(),constructs:base_image.constructs.clone(),indexes:base_image.indexes.clone()};''')
replace('        self.symbols.new_member_from(source,check,optional).unwrap()','''        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.new_members += 1; }
        self.symbols.new_member_from(source,check,optional).unwrap()''')
replace('    fn publication_instantiate(&mut self, original:SymbolRef, mapper:MapperId) -> SymbolRef {','''    fn publication_instantiate(&mut self, original:SymbolRef, mapper:MapperId) -> SymbolRef {
        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.instantiate_calls += 1; }''')
replace('            return original;','''            if self.member_publication.cost.legacy.enabled { self.member_publication.cost.invariant_reuses += 1; }
            return original;''')
replace('        if let Some(read) = self.publication_cached_read(symbol) { return read; }','''        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.read_calls += 1; }
        if let Some(read) = self.publication_cached_read(symbol) {
            if self.member_publication.cost.legacy.enabled { self.member_publication.cost.read_hits += 1; }
            return read;
        }
        if self.member_publication.cost.legacy.enabled { self.member_publication.cost.read_misses += 1; }''')
replace('        for key in keys {','''        for key in keys {
                if self.member_publication.cost.legacy.enabled { self.member_publication.cost.resets += 1; }''')
replace("impl Checker<'_, '_> {",'''impl Checker<'_, '_> {
    fn publication_copy_counts(fields: &StructuredFields) -> [u64; 5] {
