        eprintln!("MEMBER_PUBLICATION {{\\"image_calls\\":{},\\"completed_hits\\":{},\\"active_hits\\":{},\\"image_workers\\":{},\\"unsupported\\":{},\\"image_roots\\":{},\\"image_root_ns\\":{},\\"declared_calls\\":{},\\"declared_hits\\":{},\\"declared_none_hits\\":{},\\"declared_workers\\":{},\\"read_calls\\":{},\\"read_hits\\":{},\\"read_misses\\":{},\\"instantiate_calls\\":{},\\"invariant_reuses\\":{},\\"new_members\\":{},\\"resets\\":{},\\"copies\\":{:?},\\"images\\":{},\\"images_capacity\\":{},\\"done_images\\":{},\\"active_images\\":{},\\"image_members\\":{},\\"image_member_capacity\\":{},\\"image_name_bytes\\":{},\\"image_name_capacity\\":{},\\"declared_tables\\":{},\\"declared_members\\":{},\\"declared_name_bytes\\":{},\\"links\\":{},\\"links_capacity\\":{},\\"mappers\\":{},\\"mappers_capacity\\":{},\\"composites\\":{},\\"symbol_ref_bytes\\":{}}}",
