import copy,json,pathlib
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-fields-path').read_text().strip())
def validate(events):
 for e in events:
  v=e['counts']
  if e['kind']=='MEMBER_LEGACY':
   assert v['depth_at_drop']==[0,0,0]
   assert v['declared_entries']==v['calls'][2] and v['names_entries']==v['calls'][1]
   assert all(a<=b for a,b in zip(v['roots'],v['calls']))
   assert v['declared_own_hits']<=v['success'][2]
  elif e['kind']=='MEMBER_PUBLICATION':
   assert v['image_calls']==v['completed_hits']+v['active_hits']+v['image_workers']+v['unsupported']
   assert v['declared_calls']==v['declared_hits']+v['declared_none_hits']+v['declared_workers']
   assert v['read_calls']==v['read_hits']+v['read_misses']
   assert v['instantiate_calls']<=v['invariant_reuses']+v['new_members']
   if v['composites']==0: assert v['instantiate_calls']==v['invariant_reuses']+v['new_members']
  elif e['kind']=='MEMBER_SYMBOL_STORAGE':
   assert v['records']<=v['record_capacity'] and v['inline_record_bytes']==184*v['record_capacity']
def non_time(events):
 return sorted([{k:v for k,v in e['counts'].items() if k not in ['elapsed_ns','image_root_ns']}|{'kind':e['kind']} for e in events],key=lambda v:json.dumps(v,sort_keys=True))
def total(rows,role,mode,kind):
 events=[e['counts'] for row in rows if row['role']==role and row['mode']==mode and row['phase']=='time' for e in row['events'] if e['kind']==kind]
 out={}
 for e in events:
  for k,v in e.items():
   if isinstance(v,list):
    if k not in out:out[k]=copy.deepcopy(v)
    elif v and isinstance(v[0],list):out[k]=[[a+b for a,b in zip(x,y)] for x,y in zip(out[k],v)]
    else:out[k]=[a+b for a,b in zip(out[k],v)]
   elif k=='symbol_ref_bytes':
    if k in out: assert out[k]==v
    else: out[k]=v
   else:out[k]=out.get(k,0)+v
 return out
records={}
for name in ['public','storage','controls']:
 d=json.loads((r/(name+'.json')).read_text());assert d['complete']
 for row in d['rows']:validate(row['events'])
 for row in d['rows']:
  if row['phase']!='count':continue
  matching=[v for v in d['rows'] if v['role']==row['role'] and v['mode']==row['mode'] and v.get('fixture')==row.get('fixture') and v['phase'] in ['count','time','count-repeat']]
  assert len(matching)==3 and all(non_time(v['events'])==non_time(row['events']) for v in matching)
 records[name]={'children':len(d['rows']),'all_partitions_pass':True,'count_time_repeat_exact_per_owner':True}
storage=json.loads((r/'storage.json').read_text())
summary={role:{mode:{kind:total(storage['rows'],role,mode,kind) for kind in ['MEMBER_LEGACY','MEMBER_PUBLICATION','MEMBER_SYMBOL_STORAGE']} for mode in ['single','default']} for role in ['main','publication']}
bad=copy.deepcopy(next(v['events'] for v in storage['rows'] if v['role']=='publication' and v['phase']=='count'))
next(e['counts'] for e in bad if e['kind']=='MEMBER_PUBLICATION')['completed_hits']-=1
caught=False
try:validate(bad)
except AssertionError:caught=True
assert caught
record={'batches':records,'aggregate_timed_rows':summary,'counter_partition_reader_mutation_caught':True,'runtime_optimization':False}
(r/'count-reader.json').write_text(json.dumps(record,indent=2)+'\n'); assert json.loads((r/'count-reader.json').read_text())==record
print(json.dumps({'batches':records,'mutation_caught':caught,'default_publication_inline_bytes':summary['publication']['default']['MEMBER_SYMBOL_STORAGE']['inline_record_bytes']}))

