import copy
import hashlib
import json
import pathlib
import re

repo = pathlib.Path('<repo>')
r = pathlib.Path(pathlib.Path('/tmp/tsr-member-fields-path').read_text().strip())
d = json.loads((repo / 'docs/architecture/checker-member-field-cost.json').read_text())
records = d['records']

def without_times(events):
    return sorted([{'kind': e['kind'], 'counts': {k: v for k, v in e['counts'].items()
                  if k not in ('elapsed_ns', 'image_root_ns')}} for e in events],
                  key=lambda e: json.dumps(e, sort_keys=True))

def loaded(stdout):
    return [v for v in stdout.splitlines() if v.startswith(('/', 'bundled:///', '<archive>/'))
            and v.endswith(('.ts', '.tsx', '.mts', '.cts'))]

checks = {}
for name, expected in [('public.json', 20), ('storage.json', 20), ('controls.json', 66)]:
    batch = records[name]
    assert batch['complete'] and len(batch['rows']) == expected
    for row in batch['rows']:
        assert not row['timed_out'] and row['observed_inputs_stable']
        if row['role'] == 'native':
            continue
        family = [v for v in batch['rows'] if v['role'] == row['role']
                  and v['mode'] == row['mode'] and v.get('fixture') == row.get('fixture')]
        own = next(v for v in family if v['phase'] == 'ordinary')
        assert row['exit_code'] == own['exit_code']
        if name == 'controls.json':
            assert row['stdout'] == own['stdout']
        else:
            assert row['diagnostics'] == own['diagnostics']
            assert loaded(row['stdout']) == loaded(own['stdout'])
            assert len(loaded(row['stdout'])) == 265
            assert re.search(r'^Checked files:\s+202$', row['stdout'], re.M)
        if row['phase'] in ('ordinary', 'off'):
            assert row['stderr'] == '' and row['events'] == []
        if row['phase'] == 'count':
            for v in family:
                if v['phase'] in ('time', 'count-repeat'):
                    assert without_times(v['events']) == without_times(row['events'])
    checks[name] = {'children': expected, 'outputs_and_repeated_counts_pass': True}

for role in ('main', 'publication'):
    for mode in ('single', 'default'):
        row = next(v for v in records['storage.json']['rows']
                   if v['role'] == role and v['mode'] == mode and v['phase'] == 'time')
        aggregate = {}
        for event in row['events']:
            v = event['counts']
            out = aggregate.setdefault(event['kind'], {})
            for k, value in v.items():
                if k == 'symbol_ref_bytes':
                    assert out.get(k, value) == value
                    out[k] = value
                elif isinstance(value, list):
                    if k not in out:
                        out[k] = copy.deepcopy(value)
                    elif value and isinstance(value[0], list):
                        out[k] = [[a + b for a, b in zip(x, y)] for x, y in zip(out[k], value)]
                    else:
                        out[k] = [a + b for a, b in zip(out[k], value)]
                else:
                    out[k] = out.get(k, 0) + value
        expected = records['count-reader.json']['aggregate_timed_rows'][role][mode]
        for kind, value in aggregate.items():
            assert expected[kind] == value

counts = records['count-reader.json']['aggregate_timed_rows']
main = counts['main']['default']['MEMBER_LEGACY']
publication = counts['publication']['default']
assert main['calls'][2] - publication['MEMBER_LEGACY']['calls'][2] == 593159
assert sum(v[2] for v in publication['MEMBER_PUBLICATION']['copies']) == 963043
assert publication['MEMBER_SYMBOL_STORAGE']['inline_record_bytes'] == 12058624
assert publication['MEMBER_SYMBOL_STORAGE']['record_capacity'] * 184 == 12058624
assert publication['MEMBER_PUBLICATION']['symbol_ref_bytes'] == 16
for mode in ('single', 'default'):
    for fixture in ('fields', 'identities', 'reset'):
        rows = [v for v in records['controls.json']['rows'] if v['fixture'] == fixture
                and v['mode'] == mode and v['phase'] == 'ordinary']
        native = next(v for v in rows if v['role'] == 'native')
        replay = next(v for v in rows if v['role'] == 'publication')
        assert (native['stdout'], native['exit_code']) == (replay['stdout'], replay['exit_code'])
        ordinary = next(v for v in rows if v['role'] == 'main')
        if fixture == 'reset':
            assert 'TS2310' in native['stdout'] and ordinary['stdout'] == ''
        else:
            assert (ordinary['stdout'], ordinary['exit_code']) == (native['stdout'], native['exit_code'])

for name in ('legacy-storage.json', 'publication-storage.json'):
    build = records[name]
    assert build['returncode'] == 0 and build['source_unchanged_during_build']
    assert build['source_hashes_before'] == build['source_hashes_after']
assert [records['patch-replay.json'][k]['paths'] for k in ('main', 'publication')] == [5, 14]
assert all(v['matches_final_build_sources'] for v in records['patch-replay.json'].values())
assert (repo / 'docs/architecture/checker-member-field-cost.patch').read_text() == d['main_observer_patch']
assert d['runtime_optimization'] is False
result = {'checks': checks, 'aggregate_counts_match': True, 'native_control_scope_pass': True,
          'counter_partition_reader_mutation_caught': records['count-reader.json']['counter_partition_reader_mutation_caught'],
          'receipt_sha256': hashlib.sha256((repo / 'docs/architecture/checker-member-field-cost.json').read_bytes()).hexdigest()}
(r / 'receipt-reader.json').write_text(json.dumps(result, indent=2) + '\n')
assert json.loads((r / 'receipt-reader.json').read_text()) == result
print(json.dumps(result))

